data.content:
ValuativeCriterion.Existence.eq : ValuativeCriterion.Existence = (topologically @SpecializingMap).universally
@MorphismProperty.universally_le : ∀ {C : Type u_2} [inst : Category.{u_1, u_2} C] (P : MorphismProperty C),
  P.universally ≤ P
@MorphismProperty.universally_mk' : ∀ {C : Type u_2} [inst : Category.{u_1, u_2} C] (P : MorphismProperty C)
  [P.RespectsIso] {X Y : C} (g : X ⟶ Y),
  (∀ {T : C} (f : T ⟶ Y) [inst_2 : Limits.HasPullback f g], P (Limits.pullback.fst f g)) → P.universally g
@UniversallyClosed.of_comp_surjective : ∀ {X Y Z : Scheme} (f : X ⟶ Y) (g : Y ⟶ Z) [UniversallyClosed (f ≫ g)]
  [Surjective f], UniversallyClosed g
@QuasiCompact.compactSpace_of_compactSpace : ∀ {X Y : Scheme} (f : X ⟶ Y) [QuasiCompact f] [CompactSpace ↥Y],
  CompactSpace ↥X
@HasAffineProperty.iff_of_isAffine : ∀ {P : MorphismProperty Scheme} {Q : AffineTargetMorphismProperty}
  [HasAffineProperty P Q] {X Y : Scheme} {f : X ⟶ Y} [inst : IsAffine Y], P f ↔ Q f
@Scheme.Pic0Et.compactSpace : ∀ {k : Type u_1} [inst : Field k] (C : Over (Spec (CommRingCat.of k)))
  [inst_1 : SmoothOfRelativeDimension 1 C.hom] [inst_2 : IsProper C.hom] [inst_3 : GeometricallyIntegral C.hom]
  [inst_4 : Scheme.HasPicSchemeEt C], CompactSpace ↥(Scheme.Pic0SchemeEt C).left
@Scheme.Pic0Et.specializingMap : ∀ {k : Type u_1} [inst : Field k] (C : Over (Spec (CommRingCat.of k)))
  [inst_1 : SmoothOfRelativeDimension 1 C.hom] [inst_2 : IsProper C.hom] [inst_3 : GeometricallyIntegral C.hom]
  [inst_4 : Scheme.HasPicSchemeEt C], SpecializingMap ⇑(Scheme.Pic0SchemeEt C).hom
@SpecializingMap : {X : Type u_1} → {Y : Type u_2} → [TopologicalSpace X] → [TopologicalSpace Y] → (X → Y) → Prop
EXIT=0

